def restore_ip_addresses(s):
    res = []
    def bt(i, dots, cur):
        if dots == 4:
            if i == len(s):
                res.append(cur[:-1])
            return
        for l in range(1, 4):
            if i + l > len(s): break
            seg = s[i:i+l]
            if (seg[0] == '0' and len(seg) > 1) or int(seg) > 255: continue
            bt(i+l, dots+1, cur + seg + '.')
    bt(0, 0, '')
    return res

def restore_ip_addresses_loops(s):
    n = len(s); res = []
    for a in range(1, 4):
        for b in range(1, 4):
            for c in range(1, 4):
                d = n - a - b - c
                if d < 1 or d > 3: continue
                segs = [s[:a], s[a:a+b], s[a+b:a+b+c], s[a+b+c:]]
                if all(len(x) == 1 or x[0] != '0' for x in segs) and all(int(x) <= 255 for x in segs):
                    res.append('.'.join(segs))
    return res

def partition(s):
    n = len(s)
    pal = [[False]*n for _ in range(n)]
    for i in range(n): pal[i][i] = True
    for l in range(2, n+1):
        for i in range(n-l+1):
            j = i+l-1
            if s[i] == s[j] and (l == 2 or pal[i+1][j-1]):
                pal[i][j] = True
    res = []
    def bt(i, path):
        if i == n:
            res.append(path[:]); return
        for j in range(i, n):
            if pal[i][j]:
                path.append(s[i:j+1])
                bt(j+1, path)
                path.pop()
    bt(0, [])
    return res

def partition_center(s):
    n = len(s); res = []
    def bt(i, path):
        if i == n:
            res.append(path[:]); return
        for j in range(i, n):
            seg = s[i:j+1]
            if seg == seg[::-1]:
                path.append(seg)
                bt(j+1, path)
                path.pop()
    bt(0, [])
    return res

